350	fn verify_reports_unsupported_format_and_algorithm_explicitly() {
351	    let key = "00ff";
352	    let tag = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
353	    let f2 = format!(
354	        r#"{{"format":2,"algorithm":"HMAC-SHA256","key_id":"id","key_version":1,"fields":[],"tag":"{tag}"}}"#
