368	#[test]
369	fn verify_option_errors_match_sign_and_never_echo_secrets() {
370	    let key = "00ff";
371	    let rec = sign_record_bytes(key, "id", "1", &["x"]);
372	    let secret = "deadbeefcafebabedeadbeefcafebabe";
373	
374	    expect_verify_invalid(&rec, &[]); // missing --key
375	    expect_verify_invalid(&rec, &["--key"]); // missing value
376	    expect_verify_invalid(&rec, &["--key", "abc"]); // odd hex
377	    expect_verify_invalid(&rec, &["--key", "zz"]); // bad hex
378	    expect_verify_invalid(&rec, &["--key", key, "--key", key]); // duplicate
379	    expect_verify_invalid(&rec, &["--key", key, "--bogus", "x"]); // unknown
380	    expect_verify_invalid(&rec, &["--key=zz"]); // inline bad hex
381	
382	    // A bad key value must not be echoed.
383	    let stderr = expect_verify_invalid(&rec, &["--key", "abczz"]);
384	    assert!(!stderr.contains("abczz"), "stderr echoed the key: {stderr}");
385	
386	    // A valid key on a later failing option must not leak either.
387	    let stderr = expect_verify_invalid(&rec, &["--key", secret, "--bogus", "x"]);
388	    assert!(!stderr.contains(secret), "stderr echoed the key: {stderr}");
389	}
