654	/// Parse the sole JSON record on stdout, enforcing the observable contract:
655	/// exactly one line, exactly the six documented keys in documented order,
656	/// format 1, fixed algorithm name, valid version range, 64 lowercase hex tag.
657	fn parse_single_record(stdout: &[u8]) -> Record {
658	    let text = std::str::from_utf8(stdout).expect("stdout must be valid UTF-8");
659	    assert!(text.starts_with('{'), "stdout must start with the JSON object");
660	    let body = text
661	        .strip_suffix('\n')
662	        .expect("stdout must end with exactly one newline");
663	    assert!(!body.is_empty(), "stdout must contain one JSON record");
664	    assert!(!body.contains('\n'), "stdout must contain exactly one line");
665	    assert!(!body.ends_with('\r'), "line must not carry a carriage return");
666	
667	    let raw = Json::parse(body);
668	    let keys: Vec<&str> = raw.as_object().iter().map(|(k, _)| k.as_str()).collect();
669	    assert_eq!(
670	        keys,
671	        vec![
672	            "format",
673	            "algorithm",
674	            "key_id",
675	            "key_version",
676	            "fields",
677	            "tag"
678	        ],
679	        "record field structure must stay compatible"
680	    );
681	
682	    let fields = raw
683	        .get("fields")
684	        .as_array()
685	        .iter()
686	        .map(|v| v.as_str().to_string())
687	        .collect();
688	
689	    let rec = Record {
690	        format: raw.get("format").as_i64(),
691	        algorithm: raw.get("algorithm").as_str().to_string(),
692	        key_id: raw.get("key_id").as_str().to_string(),
693	        key_version: raw.get("key_version").as_i64(),
694	        fields,
695	        tag: raw.get("tag").as_str().to_string(),
696	        raw,
697	    };
698	
699	    assert_eq!(rec.format, 1, "format must always be 1");
700	    assert_eq!(rec.algorithm, "HMAC-SHA256");
701	    assert!(
702	        (1..=u32::MAX as i64).contains(&rec.key_version),
703	        "key_version out of range: {}",
704	        rec.key_version
705	    );
706	    assert_eq!(rec.tag.len(), 64, "tag must be 64 hex characters");
707	    assert!(
708	        rec.tag
709	            .bytes()
710	            .all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')),
711	        "tag must be lowercase hex, got {}",
712	        rec.tag
713	    );
714	    rec
715	}
