906	/// Run the same signing twice and return both records' parsed form plus the
907	/// exact stdout bytes, for determinism comparisons.
908	fn sign_twice(key: &str, key_id: &str, version: &str, fields: &[&str]) -> (Record, Record, Vec<u8>, Vec<u8>) {
909	    let out1 = run_sign(key, key_id, version, fields);
