1045	        ("empty-ab", &["", "ab"], "0ef917e43ad6fdd84b453b1c69d78d779a4be2b3cf2b3e20f8b61a6d8fcde7c3", "ab"),
1046	    ];
1047	    let mut tags = std::collections::HashSet::new();
1048	    let mut field_sets = std::collections::HashSet::new();
1049	    for (label, fields, golden, joined) in variants {
