1256	// verify: records hand-authored as if produced by an *external* program that
1257	// only knows the published format 1 contract.
1258	//
1259	// `sign` is never invoked in this section, so a shared bug in this crate's
1260	// sign/verify pair cannot make these tests pass. Every tag is a golden value
1261	// computed independently with Python's hmac/hashlib/struct straight from the
1262	// byte recipe printed in README.md:
1263	//
1264	//   import hmac, hashlib, struct
1265	//   def encode(key_id, version, fields):
1266	//       out = b"authnote-sign-v1"
1267	//       kb = key_id.encode()
1268	//       out += struct.pack(">Q", len(kb)) + kb
1269	//       out += struct.pack(">I", version)
1270	//       out += struct.pack(">Q", len(fields))
1271	//       for f in fields:
1272	//           fb = f.encode()
1273	//           out += struct.pack(">Q", len(fb)) + fb
1274	//       return out
1275	//   hmac.new(bytes.fromhex(key), encode(key_id, version, fields),
1276	//            hashlib.sha256).hexdigest()
1277	//
1278	// The authenticated content exercises what cannot travel through a command
1279	// line: a NUL (U+0000) flanked by text inside a field, plus Chinese, emoji
1280	// (including a UTF-16 surrogate pair spelling) and real newlines.
1281	// ---------------------------------------------------------------------------
1282	
1283	
1284	/// Independent Python golden tag over:
1285	/// key `cafecafe...cafe`, key_id `密钥\n🙂`, version 42,
1286	/// fields [`前\u{0000}后`, `世界🙂\n第二行`, ``, `世界🙂\n第二行`].
1287	const EXT_KEY: &str = "cafecafecafecafecafecafecafecafe";
1288	const EXT_TAG: &str = "7474105d623bb03a81eb00b34545fcaf7a8c24002c5a6e58ecfdc6172e1d7f9c";
1289	
1290	/// Second external producer: key/key-id for the NUL-vs-empty-field goldens.
1291	const EXT2_KEY: &str = "0123456789abcdef";
1292	const EXT2_KID: &str = "外部记录";
1293	/// Golden tag for key_id `外部记录`, version 1, one field containing only NUL.
1294	const EXT2_NUL_TAG: &str = "cc556672a3f98087fd6dac8c8a8121f517101f784cb7d163cbe4aea5dfbfc559";
1295	/// Golden tag for the same record with the field being the empty string.
1296	const EXT2_EMPTY_TAG: &str = "79548ce691de6cf5ceeeae27190de8140604615becfd21022a0d34c365f2a0db";
1297	
1298	/// Substitute the golden-tag placeholder in a hand-written external record.
1299	fn with_tag(template: &str, tag: &str) -> String {
1300	    template.replace("@@TAG@@", tag)
1301	}
