1335	#[test]
1336	fn external_format1_records_with_nul_chinese_emoji_newline_verify() {
1337	    // Three legal JSON spellings of the SAME decoded record, all carrying the
1338	    // one Python golden tag. Re-spelling, member reordering and reformatting
1339	    // must not require regenerating the tag.
1340	
1341	    // (1) Pretty-printed, members in reverse order, padded with JSON
1342	    // whitespace; Chinese/emoji written directly, NUL as \u0000, newline as
1343	    // the short \n escape.
1344	    let pretty = with_tag(
1345	        r#"
1346	  {
1347	    "tag" : "@@TAG@@",
1348	    "fields" : [ "前\u0000后" , "世界🙂\n第二行", "", "世界🙂\n第二行" ],
1349	    "key_version" : 42,
1350	    "key_id" : "密钥\n🙂",
1351	    "algorithm" : "HMAC-SHA256",
1352	    "format" : 1
1353	  }
1354	"#,
1355	        EXT_TAG,
1356	    );
1357	    expect_external_valid(pretty.as_bytes(), EXT_KEY);
1358	
1359	    // (2) Compact, canonical member order, and pure ASCII on the wire: every
1360	    // non-ASCII scalar is a \u escape, the emoji (U+1F642) is spelled as its
1361	    // legal UTF-16 surrogate pair, and newlines use \u000a instead of the
1362	    // short \n. Inside the raw string every backslash is literal, so this is
1363	    // exactly the byte sequence an ASCII-only external producer emits; after
1364	    // JSON decoding it is identical to (1). Code points: 密 U+5BC6, 钥 U+94A5,
1365	    // 前 U+524D, 后 U+540E, 世 U+4E16, 界 U+754C, 第 U+7B2C, 二 U+4E8C,
1366	    // 行 U+884C, 🙂 = U+D83D U+DE42.
1367	    let fully_escaped = with_tag(
1368	        r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"\u5bc6\u94a5\u000a\ud83d\ude42","key_version":42,"fields":["\u524d\u0000\u540e","\u4e16\u754c\ud83d\ude42\u000a\u7b2c\u4e8c\u884c","","\u4e16\u754c\ud83d\ude42\u000a\u7b2c\u4e8c\u884c"],"tag":"@@TAG@@"}"#,
1369	        EXT_TAG,
1370	    );
1371	    assert!(
1372	        fully_escaped.is_ascii(),
1373	        "variant (2) must be pure ASCII on the wire"
1374	    );
1375	    expect_external_valid(fully_escaped.as_bytes(), EXT_KEY);
1376	
1377	    // (3) Mixed/direct spelling: raw Chinese/emoji UTF-8, short \n for the
1378	    // newline, \u0000 for the NUL. Verification authenticates decoded text,
1379	    // so the conclusion must be byte-for-byte the same.
1380	    let mixed = with_tag(
1381	        r#"{"format":1,"algorithm":"HMAC-SHA256","key_id":"密钥\n🙂","key_version":42,"fields":["前\u0000后","世界🙂\n第二行","","世界🙂\n第二行"],"tag":"@@TAG@@"}"#,
1382	        EXT_TAG,
1383	    );
1384	    expect_external_valid(mixed.as_bytes(), EXT_KEY);
1385	
1386	    // The same external record under the wrong key is a plain mismatch: the
1387	    // golden value proves the positive results above are not vacuous.
1388	    expect_external_mismatch(mixed.as_bytes(), "cafecafecafecafecafecafecafecafd");
1389	}
