#[test]
fn missing_required_parameters_fail_with_exit_2() {
    expect_usage_error(&[]);
    expect_usage_error(&["--key-id", "id", "--key-version", "1"]);
    expect_usage_error(&["--key", "00ff", "--key-version", "1"]);
