65	/// Shared command-line option grammar for `sign` and `verify`.
66	///
67	/// Both subcommands accept the same two spellings for every option:
68	///   --name value     (the following argument is the value, even when it
69	///                    itself starts with "--")
70	///   --name=value     (everything after the first '=' is the value; further
71	///                    '=' characters stay part of the value)
72	/// and the two forms may be mixed freely.
73	///
74	/// What differs between the subcommands is only *which* option names are
75	/// allowed and whether a name may repeat, so each caller supplies its own
76	/// option table. Values that fail are never quoted back in error messages:
77	/// the messages name known options only, never the rejected text (which may
78	/// be a mistyped secret).
79	mod options {
80	    /// How many times an option name may appear on one command line.
81	    #[derive(Clone, Copy, PartialEq, Eq)]
82	    pub(super) enum Multiplicity {
83	        /// At most once; a second occurrence is a usage error.
84	        Single,
85	        /// Any number of times; values are kept in order of appearance.
86	        Repeated,
87	    }
88	
89	    /// One option accepted by a subcommand.
90	    pub(super) struct Spec {
91	        pub(super) name: &'static str,
92	        pub(super) multiplicity: Multiplicity,
93	    }
94	
95	    /// A matched option occurrence: the option's index in the table and its
96	    /// value for this occurrence.
97	    pub(super) struct Occurrence {
98	        pub(super) spec_index: usize,
99	        pub(super) value: String,
100	    }
101	
102	    /// Parse `args` against `specs`, preserving order of appearance.
103	    ///
104	    /// Error precedence (first problem wins, left to right):
105	    /// missing value for an option, repeated single-use option, unknown
106	    /// option or bare argument. Callers run their own semantic validation
107	    /// (hex, ranges, ...) afterwards, so grammar problems are always
108	    /// reported before invalid values.
109	    pub(super) fn parse(args: &[String], specs: &[Spec]) -> Result<Vec<Occurrence>, String> {
110	        let mut out = Vec::new();
111	        let mut seen_once = vec![false; specs.len()];
112	
113	        let mut i = 0;
114	        while i < args.len() {
115	            let arg = &args[i];
116	            // Support both "--opt value" and "--opt=value" forms. With '='
117	            // the value is everything after the FIRST '='; '=' characters
118	            // inside the value are left untouched.
119	            let (name, inline_value) = match arg.split_once('=') {
120	                Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
121	                _ => (arg.as_str(), None),
122	            };
123	            let spec_index = match specs.iter().position(|s| s.name == name) {
124	                Some(idx) => idx,
125	                // Never echo the unrecognized argument itself: it may be a
126	                // misplaced secret (e.g. a key value whose option name was
127	                // mistyped or whose value was consumed by another option).
128	                None => return Err(unknown_option_error(specs)),
129	            };
130	            let value = match inline_value {
131	                Some(v) => v,
132	                None => {
133	                    // The immediately following argument is the value, with
134	                    // no "--"-prefix special-casing: a field or key id may
135	                    // legitimately start with two dashes.
136	                    i += 1;
137	                    match args.get(i) {
138	                        Some(v) => v.clone(),
139	                        None => return Err(format!("option {name} requires a value")),
140	                    }
141	                }
142	            };
143	            if specs[spec_index].multiplicity == Multiplicity::Single && seen_once[spec_index] {
144	                return Err(format!("option {name} must be given exactly once"));
145	            }
146	            seen_once[spec_index] = true;
147	            out.push(Occurrence { spec_index, value });
148	            i += 1;
149	        }
150	        Ok(out)
151	    }
152	
153	    /// Build the fixed "unrecognized" message for a subcommand, listing only
154	    /// that subcommand's known option names. The rejected argument is never
155	    /// included.
156	    fn unknown_option_error(specs: &[Spec]) -> String {
157	        let names = specs
158	            .iter()
159	            .map(|s| s.name)
160	            .collect::<Vec<_>>()
161	            .join(", ");
162	        if specs.len() == 1 {
163	            format!("unrecognized option or argument (the only known option is {names})")
164	        } else {
165	            format!("unrecognized option or argument (known options: {names})")
166	        }
167	    }
168	}
169	
170	fn sign(args: &[String]) -> ExitCode {
171	    match parse_sign_args(args).and_then(validate_sign_args) {
172	        Ok(opts) => {
173	            let key_bytes = decode_hex(&opts.key).expect("key was validated as hex");
174	            let key_version: u32 = opts.key_version.parse().expect("version was validated");
175	            let message = encode_message(&opts.key_id, key_version, &opts.fields);
176	            let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
177	                .expect("HMAC accepts keys of any length");
178	            mac.update(&message);
179	            let tag = mac.finalize().into_bytes();
180	
181	            let fields_json = opts
182	                .fields
183	                .iter()
184	                .map(|f| format!("\"{}\"", json_escape(f)))
185	                .collect::<Vec<_>>()
186	                .join(",");
187	            println!(
188	                "{{\"format\":{FORMAT_VERSION},\"algorithm\":\"{ALGORITHM}\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
189	                json_escape(&opts.key_id),
190	                key_version,
191	                fields_json,
192	                hex_encode(&tag),
193	            );
194	            ExitCode::SUCCESS
195	        }
196	        Err(msg) => {
197	            eprintln!("authnote sign: {msg}");
198	            ExitCode::from(2)
199	        }
200	    }
201	}
202	
203	struct SignOptions {
204	    key: String,
205	    key_id: String,
206	    key_version: String,
207	    fields: Vec<String>,
208	}
209	
210	/// sign's option table: the three credential/metadata options are single
211	/// use; only --field may repeat. Names double as their stable indices.
212	const SIGN_OPTIONS: &[options::Spec] = &[
213	    options::Spec {
214	        name: "--key",
215	        multiplicity: options::Multiplicity::Single,
216	    },
217	    options::Spec {
218	        name: "--key-id",
219	        multiplicity: options::Multiplicity::Single,
220	    },
221	    options::Spec {
222	        name: "--key-version",
223	        multiplicity: options::Multiplicity::Single,
224	    },
225	    options::Spec {
226	        name: "--field",
227	        multiplicity: options::Multiplicity::Repeated,
228	    },
229	];
230	const SIGN_KEY_INDEX: usize = 0;
231	const SIGN_KEY_ID_INDEX: usize = 1;
232	const SIGN_KEY_VERSION_INDEX: usize = 2;
233	
234	fn parse_sign_args(args: &[String]) -> Result<SignOptions, String> {
235	    let mut key: Option<String> = None;
236	    let mut key_id: Option<String> = None;
237	    let mut key_version: Option<String> = None;
238	    let mut fields: Vec<String> = Vec::new();
239	
240	    for occurrence in options::parse(args, SIGN_OPTIONS)? {
241	        match occurrence.spec_index {
242	            SIGN_KEY_INDEX => key = Some(occurrence.value),
243	            SIGN_KEY_ID_INDEX => key_id = Some(occurrence.value),
244	            SIGN_KEY_VERSION_INDEX => key_version = Some(occurrence.value),
245	            // Field values are appended in order of appearance; repeats,
246	            // empty strings and text starting with "--" are kept verbatim.
247	            _ => fields.push(occurrence.value),
248	        }
249	    }
250	
251	    let key = key.ok_or("missing required option --key")?;
252	    let key_id = key_id.ok_or("missing required option --key-id")?;
253	    let key_version = key_version.ok_or("missing required option --key-version")?;
254	    Ok(SignOptions {
255	        key,
256	        key_id,
257	        key_version,
258	        fields,
259	    })
260	}
261	
262	fn validate_sign_args(opts: SignOptions) -> Result<SignOptions, String> {
263	    // Never echo the key back in error messages.
264	    validate_key_hex(&opts.key)?;
265	    if opts.key_id.is_empty() {
266	        return Err("--key-id must not be empty".to_string());
267	    }
268	    let valid_version = !opts.key_version.is_empty()
269	        && opts.key_version.bytes().all(|b| b.is_ascii_digit())
270	        && opts
271	            .key_version
272	            .parse::<u64>()
273	            .is_ok_and(|v| (1..=u32::MAX as u64).contains(&v));
274	    if !valid_version {
275	        return Err("--key-version must be a decimal integer between 1 and 4294967295".to_string());
276	    }
277	    Ok(opts)
278	}
279	
280	/// Shared key validation for `sign` and `verify`: non-empty even-length hex.
281	/// The rejected value is never included in the message.
282	fn validate_key_hex(key: &str) -> Result<(), String> {
283	    if key.is_empty() || key.len() % 2 != 0 || !key.bytes().all(|b| b.is_ascii_hexdigit()) {
284	        return Err("--key must be a non-empty, even-length hexadecimal string".to_string());
285	    }
286	    Ok(())
287	}
