292	
293	fn verify(args: &[String]) -> ExitCode {
294	    // verify deliberately shares sign's option grammar through the common
295	    // parser but declares its own, narrower table: --key is the only known
296	    // option, so every sign-only option (--key-id, --key-version, --field)
297	    // is rejected here as unrecognized. Values that fail are never echoed
298	    // (they could be a mistyped secret).
299	    const VERIFY_OPTIONS: &[options::Spec] = &[options::Spec {
300	        name: "--key",
301	        multiplicity: options::Multiplicity::Single,
302	    }];
303	
304	    let parse = (|| -> Result<String, String> {
305	        let occurrences = options::parse(args, VERIFY_OPTIONS)?;
306	        // The parser enforces "at most one --key"; take it if present.
307	        let key = occurrences
308	            .first()
309	            .map(|o| o.value.clone())
310	            .ok_or("missing required option --key")?;
311	        validate_key_hex(&key)?;
312	        Ok(key)
313	    })();
314	
315	    let key_hex = match parse {
316	        Ok(key) => key,
317	        Err(msg) => {
318	            eprintln!("authnote verify: {msg}");
319	            return ExitCode::from(2);
320	        }
321	    };
322	
323	    // Read the whole standard input. It must be one JSON record and nothing
324	    // else; trailing non-whitespace is a malformed invocation, not a mismatch.
325	    let mut input = Vec::new();
326	    if let Err(e) = std::io::stdin().read_to_end(&mut input) {
327	        eprintln!("authnote verify: failed to read standard input: {e}");
328	        return ExitCode::from(2);
329	    }
330	
331	    let outcome = verify_input(&input, &key_hex);
332	    match outcome {
333	        VerifyOutcome::Valid => {
334	            println!("{{\"valid\":true}}");
335	            ExitCode::SUCCESS
336	        }
337	        VerifyOutcome::Mismatch => {
338	            println!("{{\"valid\":false}}");
339	            ExitCode::from(1)
340	        }
341	        VerifyOutcome::Invalid(msg) => {
342	            eprintln!("authnote verify: {msg}");
343	            ExitCode::from(2)
344	        }
345	    }
346	}
347	
348	#[derive(Debug)]
349	enum VerifyOutcome {
350	    Valid,
351	    Mismatch,
352	    Invalid(String),
353	}
354	
355	fn verify_input(input: &[u8], key_hex: &str) -> VerifyOutcome {
356	    let text = match std::str::from_utf8(input) {
357	        Ok(t) => t,
358	        // Still parse to distinguish a structurally invalid record from a
359	        // record whose text merely contains bytes Rust rejects; JSON itself
360	        // forbids raw non-UTF-8, so this is always "corrupt input" here.
361	        Err(_) => return VerifyOutcome::Invalid("input is not valid UTF-8 JSON text".to_string()),
362	    };
363	
364	    let value = match json::parse_single(text) {
365	        Ok(v) => v,
366	        Err(msg) => return VerifyOutcome::Invalid(msg),
367	    };
368	    let record = match record_from_json(&value) {
369	        Ok(r) => r,
370	        Err(msg) => return VerifyOutcome::Invalid(msg),
371	    };
372	
373	    let key_bytes = decode_hex(key_hex).expect("key was validated as hex");
374	    let message = encode_message(&record.key_id, record.key_version, &record.fields);
375	    let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
376	        .expect("HMAC accepts keys of any length");
377	    mac.update(&message);
378	
379	    let expected_tag = mac.finalize().into_bytes();
380	    let given_tag = &record.tag;
381	
382	    // Both sides are 32 bytes; compare in constant time so a mismatch cannot
383	    // be recovered one byte at a time through timing.
384	    debug_assert_eq!(expected_tag.len(), given_tag.len());
385	    if expected_tag.len() != given_tag.len() {
386	        return VerifyOutcome::Mismatch;
387	    }
388	    let mut diff = 0u8;
389	    for (a, b) in expected_tag.iter().zip(given_tag.iter()) {
390	        diff |= a ^ b;
391	    }
392	    if diff == 0 {
393	        VerifyOutcome::Valid
394	    } else {
395	        VerifyOutcome::Mismatch
396	    }
397	}
398	
399	/// Decode the tag as exactly 32 bytes of case-insensitive hexadecimal.
400	fn decode_tag(s: &str) -> Result<Vec<u8>, String> {
401	    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_hexdigit()) {
402	        return Err("tag must be exactly 64 hexadecimal characters (32 bytes)".to_string());
403	    }
404	    decode_hex(s).map_err(|e| format!("tag is not valid hexadecimal: {e}"))
405	}
406	
407	struct AuthRecord {
408	    key_id: String,
409	    key_version: u32,
410	    fields: Vec<String>,
411	    tag: Vec<u8>,
412	}
413	
414	/// Validate the decoded JSON value as exactly one format-1 authentication
415	/// record and pull out the authenticated fields. Structural problems (missing
416	/// members, wrong types, duplicates inside `fields`, ...) are caller errors:
417	/// they must produce exit 2, never a `{"valid":false}` mismatch result.
418	fn record_from_json(value: &json::JsonValue) -> Result<AuthRecord, String> {
419	    let obj = match value {
420	        json::JsonValue::Object(entries) => entries,
421	        _ => return Err("record must be a single JSON object".to_string()),
422	    };
423	
424	    // Require precisely the six documented members, each present exactly once;
425	    // the parser already rejects duplicate member names, and an empty object
426	    // naturally fails the "missing required member" checks below.
427	    let mut format: Option<&json::JsonValue> = None;
428	    let mut algorithm: Option<&json::JsonValue> = None;
429	    let mut key_id: Option<&json::JsonValue> = None;
430	    let mut key_version: Option<&json::JsonValue> = None;
431	    let mut fields: Option<&json::JsonValue> = None;
432	    let mut tag: Option<&json::JsonValue> = None;
433	    for (name, val) in obj {
434	        let slot = match name.as_str() {
435	            "format" => &mut format,
436	            "algorithm" => &mut algorithm,
437	            "key_id" => &mut key_id,
438	            "key_version" => &mut key_version,
439	            "fields" => &mut fields,
440	            "tag" => &mut tag,
441	            // Do not echo the unknown member name: it comes from the input
442	            // record, which error messages must never quote back.
443	            _ => return Err("record contains an unexpected member".to_string()),
444	        };
445	        if slot.is_some() {
446	            // The strict parser rejects duplicates already; keep a defense in
447	            // depth without quoting the member name from the input twice.
448	            return Err("record contains a duplicate member".to_string());
449	        }
450	        *slot = Some(val);
451	    }
452	
453	    // Unsupported format/algorithm must be reported as such explicitly: we do
454	    // not silently fall back to the current rules and compute a result.
455	    let format = format.ok_or("record is missing required member \"format\"")?;
456	    match format {
457	        json::JsonValue::Number(n) if *n == i128::from(FORMAT_VERSION) => {}
458	        json::JsonValue::Number(_) => {
459	            return Err("unsupported record format version; only format 1 is supported".to_string())
460	        }
461	        _ => return Err("member \"format\" must be an integer".to_string()),
462	    }
463	
464	    let algorithm = algorithm.ok_or("record is missing required member \"algorithm\"")?;
465	    match algorithm {
466	        json::JsonValue::String(s) if s == ALGORITHM => {}
467	        json::JsonValue::String(_) => {
468	            return Err(
469	                "unsupported algorithm in record; only HMAC-SHA256 is supported".to_string(),
470	            )
471	        }
472	        _ => return Err("member \"algorithm\" must be a string".to_string()),
473	    }
474	
475	    let key_id = key_id.ok_or("record is missing required member \"key_id\"")?;
476	    let key_id = match key_id {
477	        json::JsonValue::String(s) if !s.is_empty() => s.clone(),
478	        json::JsonValue::String(_) => {
479	            return Err("member \"key_id\" must not be empty".to_string())
480	        }
481	        _ => return Err("member \"key_id\" must be a string".to_string()),
482	    };
483	
484	    let key_version = key_version.ok_or("record is missing required member \"key_version\"")?;
485	    let key_version = match key_version {
486	        json::JsonValue::Number(n) => {
487	            if *n < 1 || *n > i128::from(u32::MAX) {
488	                return Err(
489	                    "member \"key_version\" is outside the supported range 1..=4294967295"
490	                        .to_string(),
491	                );
492	            }
493	            *n as u32
494	        }
495	        _ => return Err("member \"key_version\" must be an integer".to_string()),
496	    };
497	
498	    let fields_val = fields.ok_or("record is missing required member \"fields\"")?;
499	    let fields = match fields_val {
500	        json::JsonValue::Array(items) => {
501	            let mut out = Vec::with_capacity(items.len());
502	            for item in items {
503	                match item {
504	                    json::JsonValue::String(s) => out.push(s.clone()),
505	                    _ => {
506	                        return Err(
507	                            "every element of member \"fields\" must be a string".to_string()
508	                        )
509	                    }
510	                }
511	            }
512	            out
513	        }
514	        _ => return Err("member \"fields\" must be an array of strings".to_string()),
515	    };
516	
517	    let tag_val = tag.ok_or("record is missing required member \"tag\"")?;
518	    let tag = match tag_val {
519	        json::JsonValue::String(s) => decode_tag(s)?,
520	        _ => return Err("member \"tag\" must be a string".to_string()),
521	    };
522	
523	    Ok(AuthRecord {
524	        key_id,
525	        key_version,
526	        fields,
527	        tag,
528	    })
529	}
530	
531	/// Canonical byte encoding of the authenticated content.
532	///
533	/// Layout (all integers big-endian, all text UTF-8, no trimming or escaping):
534	///   DOMAIN_SEPARATOR ("authnote-sign-v1", 16 ASCII bytes)
535	///   u64 length of key-id, then key-id bytes
536	///   u32 key version
537	///   u64 field count
538	///   for each field in order: u64 length of field, then field bytes
539	///
540	/// Length prefixes make field boundaries unambiguous: ["ab","c"] and
541	/// ["a","bc"] encode differently, as do zero fields and one empty field.
542	fn encode_message(key_id: &str, key_version: u32, fields: &[String]) -> Vec<u8> {
543	    let mut out = Vec::new();
544	    out.extend_from_slice(DOMAIN_SEPARATOR);
545	    push_len_prefixed(&mut out, key_id.as_bytes());
546	    out.extend_from_slice(&key_version.to_be_bytes());
547	    out.extend_from_slice(&(fields.len() as u64).to_be_bytes());
548	    for field in fields {
549	        push_len_prefixed(&mut out, field.as_bytes());
550	    }
551	    out
552	}
553	
554	fn push_len_prefixed(out: &mut Vec<u8>, bytes: &[u8]) {
555	    out.extend_from_slice(&(bytes.len() as u64).to_be_bytes());
556	    out.extend_from_slice(bytes);
557	}
558	
559	fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
560	    (0..s.len())
561	        .step_by(2)
562	        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
563	        .collect()
564	}
565	
566	fn hex_encode(bytes: &[u8]) -> String {
567	    bytes.iter().map(|b| format!("{b:02x}")).collect()
568	}
569	
570	fn json_escape(s: &str) -> String {
571	    let mut out = String::with_capacity(s.len());
572	    for c in s.chars() {
573	        match c {
574	            '"' => out.push_str("\\\""),
575	            '\\' => out.push_str("\\\\"),
576	            '\n' => out.push_str("\\n"),
577	            '\r' => out.push_str("\\r"),
578	            '\t' => out.push_str("\\t"),
579	            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
580	            c => out.push(c),
581	        }
582	    }
583	    out
584	}
