// ---------------------------------------------------------------------------
// verify: member names are matched by their JSON-decoded text
//
// An external program may re-spell a member name with \u escapes; the name is
// recognized by the decoded text, so the rewrite stays valid. The same rule
// makes two spellings of one decoded name a duplicate member (exit 2), and
// never promotes a look-alike name (case/whitespace/extra characters) into a
// known member.
// ---------------------------------------------------------------------------

/// Replace the JSON spelling of one member name inside a signed record.
fn respell_member(record: &str, canonical: &str, spelling: &str) -> String {
    let needle = format!("\"{canonical}\":");
    assert!(record.contains(&needle), "record must contain member {canonical}");
    record.replacen(&needle, &format!("\"{spelling}\":"), 1)
}
