/// Overwrite the spelling of one member name in a compact signed record.
/// `spelling` is the raw JSON text of the replacement name (without quotes),
/// so escapes can be supplied exactly as they appear on the wire.
fn respell_member(record: &str, canonical: &str, spelling: &str) -> String {
    let needle = format!("\"{canonical}\":");
    assert!(
        record.matches(&needle).count() == 1,
        "record must contain member {canonical} exactly once: {record}"
    );
    record.replacen(&needle, &format!("\"{spelling}\":"), 1)
}
